  1638	<script>
  1639	function showPage(id) {
  1640	  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  1641	  document.getElementById(id).classList.add('active');
  1642	  window.scrollTo({ top: 0, behavior: 'smooth' });
  1643	  if (id !== 'gateway') initReveal();
  1644	}
  1645	
  1646	function gotoSection(id) {
  1647	  const el = document.getElementById(id);
  1648	  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  1649	}
  1650	
  1651	function initReveal() {
  1652	  const observer = new IntersectionObserver((entries) => {
  1653	    entries.forEach(entry => {
  1654	      if (entry.isIntersecting) {
  1655	        entry.target.classList.add('visible');
  1656	        observer.unobserve(entry.target);
  1657	      }
  1658	    });
  1659	  }, { threshold: 0.1 });
  1660	
  1661	  document.querySelectorAll('.reveal').forEach(el => {
  1662	    el.classList.remove('visible');
  1663	    observer.observe(el);
  1664	  });
  1665	}
  1666	
  1667	// Stagger reveal delays
  1668	document.querySelectorAll('.steps .step').forEach((el, i) => {
  1669	  el.style.transitionDelay = `${i * 0.1}s`;
  1670	});
  1671	document.querySelectorAll('.pathway-card').forEach((el, i) => {
  1672	  el.style.transitionDelay = `${(i % 4) * 0.08}s`;
  1673	});
  1674	</script>
