  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}}

/* LAYER 1 — Desaturated sky, very faint foundation */
.hero-layer-desat {{
  position: absolute;
  inset: 0;
  background-image: url('data:image/png;base64,{desat}');
  background-size: cover;
  background-position: center 30%;
  opacity: 0.55;
  mix-blend-mode: multiply;
  z-index: 1;
}}

/* Vignette fade — image dissolves at all four edges */
.hero-layer-desat::after {{
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 100% 100% at 50% 50%,
      transparent 35%,
      rgba(253,250,244,0.6) 65%,
      rgba(253,250,244,0.97) 85%,
      var(--off-white) 100%
    );
}}

/* LAYER 2 — Soft light color overlay, recedes under text via blend mode */
.hero-layer-soft {{
  position: absolute;
  inset: 0;
  background-image: url('data:image/png;base64,{soft}');
  background-size: cover;
  background-position: center 30%;
  opacity: 0.25;
  mix-blend-mode: soft-light;
  z-index: 2;
}}

/* LAYER 3 — Ambient gradient atmosphere */
.hero-layer-atmos {{
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 50% at 50% 20%, rgba(201,168,76,0.06) 0%, transparent 60%),
