.hero-content {{
  position: relative;
  z-index: 10;
  text-align: center;
  max-width: 860px;
  padding: 0 48px;
  animation: riseIn 1.6s cubic-bezier(0.22,1,0.36,1) both;
}}

@keyframes riseIn {{
  from {{ opacity: 0; transform: translateY(36px); }}
  to   {{ opacity: 1; transform: translateY(0); }}
}}

/* Eyebrow */
.eyebrow {{
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 5px;
  text-transform: uppercase;
  color: var(--blue-deep);
  margin-bottom: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
}}

.eyebrow::before, .eyebrow::after {{
  content: '';
  width: 48px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--blue-mid), transparent);
}}

/* Main title */
.hero-title {{
  font-family: var(--font-display);
  font-size: clamp(46px, 7.5vw, 84px);
  font-weight: 400;
  line-height: 1.06;
  color: var(--text);
  margin-bottom: 28px;
  letter-spacing: -0.5px;
