}}

.hero-title em {{
  font-style: italic;
  color: var(--gold);
}}

.hero-title .thin {{
  font-weight: 300;
  color: var(--blue-deep);
  font-style: normal;
}}

/* Subtitle */
.hero-sub {{
  font-family: var(--font-body);
  font-size: 20px;
  font-style: italic;
  color: var(--text-light);
  line-height: 1.65;
  max-width: 540px;
  margin: 0 auto 52px;
}}

/* Buttons */
.btn-row {{
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}}

.btn-gold {{
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  background: var(--gold);
  color: var(--white);
  border: none;
  padding: 16px 44px;
  cursor: pointer;
  transition: all 0.3s ease;
  text-decoration: none;
  display: inline-block;
}}

.btn-gold:hover {{
  background: var(--gold-lt);
  transform: translateY(-2px);
  box-shadow: 0 10px 36px rgba(201,168,76,0.28);
}}

.btn-ghost {{
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  background: transparent;
  color: var(--blue-deep);
  border: 1px solid rgba(74,122,155,0.4);
  padding: 15px 44px;
  cursor: pointer;
  transition: all 0.3s ease;
  text-decoration: none;
  display: inline-block;
}}

.btn-ghost:hover {{
  background: rgba(74,122,155,0.07);
  border-color: var(--blue-deep);
}}

/* ── BELOW HERO — fades smoothly into page ──────────────── */
.below-hero {{
  position: relative;
  z-index: 5;
  background: var(--off-white);
  padding: 80px 48px;
  text-align: center;
}}

.below-hero::before {{
  content: '';
  position: absolute;
  top: -60px; left: 0; right: 0;
  height: 60px;
  background: linear-gradient(to bottom, transparent, var(--off-white));
  pointer-events: none;
}}

.below-title {{
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 40px;
}}

.partner-row {{
  display: flex;
  justify-content: center;
  gap: 56px;
  flex-wrap: wrap;
}}

.partner {{
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--text-light);
  opacity: 0.6;
  transition: opacity 0.25s;
}}

.partner:hover {{ opacity: 1; color: var(--gold); }}

</style>
</head>
<body>

<div class="hero">

  <!-- Layer 1: Desaturated image foundation -->
  <div class="hero-layer-desat"></div>

  <!-- Layer 2: Soft light color bleed -->
  <div class="hero-layer-soft"></div>

  <!-- Layer 3: Atmospheric gradient -->
  <div class="hero-layer-atmos"></div>

  <!-- Layer 4: Text content -->
  <div class="hero-content">
    <div class="eyebrow">Faith &nbsp;·&nbsp; Vocation &nbsp;·&nbsp; Restoration</div>
    <h1 class="hero-title">
      You were made<br>
      to <em>work.</em><br>
      <span class="thin">We will equip you.</span>
    </h1>
    <p class="hero-sub">
      Free, industry-recognized certifications for displaced workers —
      supported by a community that understands the obligation to equip.
    </p>
    <div class="btn-row">
      <a href="#" class="btn-gold">Begin Your Pathway</a>
      <a href="#" class="btn-ghost">Our Mission</a>
    </div>
  </div>

</div>

<!-- Page continues below, seamlessly -->
<div class="below-hero">
  <div class="below-title">Credentials from the world's leading institutions</div>
  <div class="partner-row">
    <span class="partner">IBM</span>
    <span class="partner">Google</span>
    <span class="partner">Microsoft</span>
    <span class="partner">Fortinet</span>
    <span class="partner">freeCodeCamp</span>
  </div>
</div>

</body>
</html>'''

with open('/mnt/user-data/outputs/tmi-hero-sample.html', 'w') as f:
