// ── AUTH ────────────────────────────────────────────────
async function submitApplication() {{
  const name = document.getElementById('apply-name').value.trim();
  const email = document.getElementById('apply-email').value.trim();
  const password = document.getElementById('apply-password').value;
  const pathway = document.getElementById('apply-pathway').value;
  const bio = document.getElementById('apply-bio').value.trim();
  const status = document.getElementById('apply-status');

  if (!name || !email || !password) {{
    status.innerHTML = '<div class="form-error">Please fill in name, email, and password.</div>';
    return;
  }}

  status.innerHTML = '<div style="font-family:var(--font-u);font-size:12px;color:var(--text-light);">Submitting...</div>';

  try {{
    const {{ data, error }} = await sb.auth.signUp({{
      email, password,
      options: {{ data: {{ full_name: name, pathway: pathway, bio: bio }} }}
    }});
    if (error) throw error;
    status.innerHTML = '<div class="form-success">Application submitted! Check your email to confirm your account, then sign in to access your dashboard.</div>';
  }} catch(e) {{
    status.innerHTML = `<div class="form-error">${{e.message}}</div>`;
  }}
}}

async function signIn() {{
  const email = document.getElementById('login-email').value.trim();
  const password = document.getElementById('login-password').value;
  const status = document.getElementById('login-status');

  if (!email || !password) {{
    status.innerHTML = '<div class="form-error">Please enter email and password.</div>';
    return;
  }}

  status.innerHTML = '<div style="font-family:var(--font-u);font-size:12px;color:var(--text-light);">Signing in...</div>';

  try {{
    const {{ data, error }} = await sb.auth.signInWithPassword({{ email, password }});
    if (error) throw error;
    closeModal('login');
    updateNavForUser(data.user);
    showSection('dashboard');
    loadDashboard(data.user);
  }} catch(e) {{
    status.innerHTML = `<div class="form-error">${{e.message}}</div>`;
  }}
}}

async function signOut() {{
  await sb.auth.signOut();
  document.getElementById('nav-auth').innerHTML = `
    <a href="#" class="btn-nav btn-nav-ghost" onclick="openModal('login')">Sign In</a>
    <a href="#" class="btn-nav btn-nav-gold" onclick="openModal('apply')">Apply Free</a>
  `;
  showSection('home');
  setSchoolMode(false);
}}

function updateNavForUser(user) {{
  const name = user.user_metadata?.full_name || user.email;
  document.getElementById('nav-auth').innerHTML = `
    <span style="font-family:var(--font-u);font-size:11px;color:var(--text-light);margin-right:8px;">${{name.split(' ')[0]}}</span>
    <a href="#" class="btn-nav btn-nav-gold" onclick="showSection('dashboard')">My Dashboard</a>
  `;
}}

function loadDashboard(user) {{
  const name = user.user_metadata?.full_name || 'Student';
  const pathway = user.user_metadata?.pathway || 'Pathway not yet assigned';
  document.getElementById('dash-name').textContent = name.split(' ')[0];
  document.getElementById('dash-pathway').innerHTML = `Pathway: ${{pathway}} &nbsp;·&nbsp; Status: <span class="status-badge status-active">Active</span>`;
}}

async function sendMessage() {{
  const msg = document.getElementById('msg-input').value.trim();
  const status = document.getElementById('msg-status');
  if (!msg) return;
  const {{ data: {{ user }} }} = await sb.auth.getUser();
  if (!user) {{ status.innerHTML='<div class="form-error">Please sign in.</div>'; return; }}
  try {{
    await sb.from('messages').insert({{ user_id: user.id, message: msg, created_at: new Date() }});
    document.getElementById('msg-input').value = '';
    status.innerHTML = '<div class="form-success">Message sent. Your advisor will respond by email.</div>';
  }} catch(e) {{
    status.innerHTML = `<div class="form-error">Could not send: ${{e.message}}</div>`;
  }}
}}

async function logCompletion() {{
  const item = document.getElementById('completion-input').value.trim();
  const status = document.getElementById('completion-status');
  if (!item) return;
  const {{ data: {{ user }} }} = await sb.auth.getUser();
  if (!user) {{ status.innerHTML='<div class="form-error">Please sign in.</div>'; return; }}
  try {{
    await sb.from('completions').insert({{ user_id: user.id, item: item, completed_at: new Date() }});
    document.getElementById('completion-input').value = '';
    status.innerHTML = '<div class="form-success">Logged! Keep going.</div>';
  }} catch(e) {{
    status.innerHTML = `<div class="form-error">Could not log: ${{e.message}}</div>`;
  }}
}}

// ── SESSION RESTORE ─────────────────────────────────────
sb.auth.getSession().then(({{ data: {{ session }} }}) => {{
  if (session?.user) {{
    updateNavForUser(session.user);
  }}
}});

// ── REVEAL ON SCROLL ────────────────────────────────────
function observeReveal() {{
  const obs = new IntersectionObserver(entries => {{
    entries.forEach(e => {{ if(e.isIntersecting) {{ e.target.classList.add('visible'); obs.unobserve(e.target); }} }});
  }}, {{threshold: 0.08}});
  document.querySelectorAll('.reveal:not(.visible)').forEach(el => obs.observe(el));
}}
observeReveal();
</script>
