.btn-nav-ghost:hover{{background:rgba(74,122,155,0.07);}}
.btn-nav-gold:hover{{background:var(--gold-lt);}}

/* ── PAGE WRAPPER ─────────────────────────────────────── */
.page{{position:relative;z-index:10;}}
.page-section{{display:none;}}
.page-section.active{{display:block;}}

/* ── HERO ─────────────────────────────────────────────── */
.hero{{
  min-height:100vh;display:flex;align-items:center;justify-content:center;
  padding:120px 48px 80px;overflow:hidden;position:relative;
}}
.hero::before{{content:'';position:absolute;width:700px;height:700px;border-radius:50%;border:1px solid rgba(201,168,76,0.1);top:50%;left:50%;transform:translate(-50%,-50%);pointer-events:none;}}
.hero-inner{{max-width:860px;text-align:center;animation:riseIn 1.6s cubic-bezier(0.22,1,0.36,1) both;}}
@keyframes riseIn{{from{{opacity:0;transform:translateY(36px);}}to{{opacity:1;transform:translateY(0);}}}}
.eyebrow{{font-family:var(--font-u);font-size:10px;font-weight:500;letter-spacing:5px;text-transform:uppercase;color:var(--blue-deep);margin-bottom:32px;display:flex;align-items:center;justify-content:center;gap:18px;}}
.eyebrow::before,.eyebrow::after{{content:'';width:48px;height:1px;background:linear-gradient(90deg,transparent,var(--blue-mid),transparent);}}
.hero-title{{font-family:var(--font-d);font-size:clamp(44px,7vw,80px);font-weight:400;line-height:1.06;color:var(--text);margin-bottom:28px;letter-spacing:-0.5px;}}
.hero-title em{{font-style:italic;color:var(--gold);}}
.hero-title .thin{{font-weight:300;color:var(--blue-deep);font-style:normal;}}
.hero-sub{{font-family:var(--font-b);font-size:20px;font-style:italic;color:var(--text-light);line-height:1.65;max-width:540px;margin:0 auto 52px;}}
.btn-row{{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;}}
.btn-gold{{font-family:var(--font-u);font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;background:var(--gold);color:var(--white);border:none;padding:16px 44px;cursor:pointer;transition:all 0.3s ease;text-decoration:none;display:inline-block;}}
.btn-gold:hover{{background:var(--gold-lt);transform:translateY(-2px);box-shadow:0 10px 36px rgba(201,168,76,0.28);}}
.btn-ghost{{font-family:var(--font-u);font-size:11px;font-weight:500;letter-spacing:2.5px;text-transform:uppercase;background:transparent;color:var(--blue-deep);border:1px solid rgba(74,122,155,0.4);padding:15px 44px;cursor:pointer;transition:all 0.3s ease;text-decoration:none;display:inline-block;}}
.btn-ghost:hover{{background:rgba(74,122,155,0.07);border-color:var(--blue-deep);}}

/* ── FADE RULE ────────────────────────────────────────── */
.fade-rule{{width:100%;height:1px;background:linear-gradient(90deg,transparent,rgba(201,168,76,0.25),transparent);margin:0;}}

/* ── SECTION ──────────────────────────────────────────── */
section{{position:relative;z-index:5;padding:80px 48px;}}
.section-inner{{max-width:1040px;margin:0 auto;}}
.section-label{{font-family:var(--font-u);font-size:10px;font-weight:500;letter-spacing:4px;text-transform:uppercase;color:var(--gold);margin-bottom:14px;}}
.section-title{{font-family:var(--font-d);font-size:clamp(28px,4vw,44px);font-weight:400;color:var(--text);line-height:1.2;margin-bottom:48px;}}
.section-title em{{font-style:italic;color:var(--blue-deep);}}

/* ── QUOTE ────────────────────────────────────────────── */
.quote-wrap{{max-width:720px;margin:0 auto;text-align:center;padding:48px 32px;}}
.quote-text{{font-family:var(--font-d);font-size:clamp(18px,2.5vw,26px);font-style:italic;color:var(--text);line-height:1.6;margin-bottom:20px;}}
.quote-ref{{font-family:var(--font-u);font-size:10px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--gold);}}

/* ── STAT ROW ─────────────────────────────────────────── */
.stat-row{{display:flex;justify-content:center;gap:72px;padding:48px;flex-wrap:wrap;}}
.stat{{text-align:center;}}
.stat-num{{font-family:var(--font-d);font-size:48px;font-weight:400;color:var(--gold);line-height:1;margin-bottom:6px;}}
.stat-label{{font-family:var(--font-u);font-size:10px;font-weight:400;letter-spacing:1.5px;text-transform:uppercase;color:var(--text-light);}}

/* ── CARDS ────────────────────────────────────────────── */
.card-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;}}
.card{{background:rgba(255,255,255,0.68);backdrop-filter:blur(12px);border:1px solid rgba(201,168,76,0.2);padding:36px 30px;position:relative;overflow:hidden;transition:all 0.35s ease;}}
.card::before{{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:0;transition:opacity 0.35s;}}
.card:hover{{transform:translateY(-4px);box-shadow:0 16px 48px rgba(138,175,200,0.2);border-color:rgba(201,168,76,0.4);}}
.card:hover::before{{opacity:1;}}
.card-icon{{font-size:30px;margin-bottom:18px;display:block;}}
.card-title{{font-family:var(--font-d);font-size:20px;font-weight:500;color:var(--text);margin-bottom:10px;line-height:1.25;}}
.card-body{{font-family:var(--font-u);font-size:13px;font-weight:300;color:var(--text-light);line-height:1.75;}}
.card-meta{{display:flex;gap:8px;margin-top:18px;flex-wrap:wrap;}}
.tag{{font-family:var(--font-u);font-size:9px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;color:var(--blue-deep);border:1px solid rgba(74,122,155,0.3);padding:3px 10px;}}
.tag-gold{{color:var(--gold);border-color:rgba(201,168,76,0.35);}}

/* ── PATHWAY GRID ─────────────────────────────────────── */
.pathway-grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;}}
.pathway-card{{background:rgba(255,255,255,0.72);backdrop-filter:blur(8px);border:1px solid rgba(138,175,200,0.28);padding:24px 18px;text-align:center;cursor:pointer;transition:all 0.3s ease;position:relative;overflow:hidden;}}
.pathway-card::after{{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--blue-mid),var(--gold));transform:scaleX(0);transition:transform 0.3s ease;}}
.pathway-card:hover{{background:rgba(255,255,255,0.92);border-color:rgba(74,122,155,0.45);transform:translateY(-3px);box-shadow:0 8px 32px rgba(138,175,200,0.22);}}
.pathway-card:hover::after{{transform:scaleX(1);}}
.pc-icon{{font-size:28px;margin-bottom:10px;}}
.pc-title{{font-family:var(--font-d);font-size:15px;font-weight:500;color:var(--text);margin-bottom:5px;line-height:1.25;}}
.pc-sub{{font-family:var(--font-u);font-size:10px;font-weight:300;color:var(--text-light);letter-spacing:0.3px;margin-bottom:8px;}}
.pc-duration{{font-family:var(--font-u);font-size:9px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold);}}

/* ── MODAL / OVERLAY ──────────────────────────────────── */
.modal-overlay{{position:fixed;inset:0;background:rgba(30,30,30,0.5);backdrop-filter:blur(8px);z-index:2000;display:none;align-items:center;justify-content:center;padding:24px;}}
.modal-overlay.open{{display:flex;}}
.modal{{background:var(--off-white);max-width:520px;width:100%;padding:52px 48px;position:relative;max-height:90vh;overflow-y:auto;border-top:3px solid var(--gold);}}
.modal-close{{position:absolute;top:20px;right:24px;background:none;border:none;font-size:20px;cursor:pointer;color:var(--text-light);font-family:var(--font-u);}}
.modal-title{{font-family:var(--font-d);font-size:28px;font-weight:400;color:var(--text);margin-bottom:8px;}}
.modal-sub{{font-family:var(--font-b);font-size:15px;font-style:italic;color:var(--text-light);margin-bottom:32px;line-height:1.5;}}
.form-group{{margin-bottom:20px;}}
.form-label{{font-family:var(--font-u);font-size:10px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--text-light);display:block;margin-bottom:8px;}}
.form-input{{width:100%;background:rgba(255,255,255,0.8);border:1px solid rgba(201,168,76,0.25);padding:12px 16px;font-family:var(--font-u);font-size:14px;color:var(--text);outline:none;transition:border-color 0.25s;}}
.form-input:focus{{border-color:var(--gold);}}
.form-select{{width:100%;background:rgba(255,255,255,0.8);border:1px solid rgba(201,168,76,0.25);padding:12px 16px;font-family:var(--font-u);font-size:14px;color:var(--text);outline:none;cursor:pointer;}}
.form-textarea{{width:100%;background:rgba(255,255,255,0.8);border:1px solid rgba(201,168,76,0.25);padding:12px 16px;font-family:var(--font-u);font-size:14px;color:var(--text);outline:none;resize:vertical;min-height:80px;}}
.form-error{{font-family:var(--font-u);font-size:11px;color:#c0392b;margin-top:4px;}}
.form-success{{font-family:var(--font-u);font-size:13px;color:#27ae60;text-align:center;padding:12px;background:rgba(39,174,96,0.08);border:1px solid rgba(39,174,96,0.2);margin-top:12px;}}

/* ── DASHBOARD ────────────────────────────────────────── */
.dash-header{{background:rgba(255,255,255,0.75);backdrop-filter:blur(12px);border:1px solid rgba(201,168,76,0.2);padding:32px 36px;margin-bottom:24px;}}
.dash-welcome{{font-family:var(--font-d);font-size:26px;font-weight:400;color:var(--text);margin-bottom:4px;}}
.dash-welcome em{{color:var(--gold);font-style:italic;}}
.dash-sub{{font-family:var(--font-u);font-size:12px;font-weight:300;color:var(--text-light);letter-spacing:0.5px;}}
.dash-grid{{display:grid;grid-template-columns:1fr 2fr;gap:24px;}}
.dash-card{{background:rgba(255,255,255,0.72);backdrop-filter:blur(10px);border:1px solid rgba(201,168,76,0.18);padding:28px;}}
.dash-card-title{{font-family:var(--font-u);font-size:10px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin-bottom:16px;}}
.progress-item{{margin-bottom:16px;}}
.progress-name{{font-family:var(--font-u);font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;}}
.progress-bar-wrap{{background:rgba(201,168,76,0.1);height:6px;position:relative;}}
.progress-bar{{background:linear-gradient(90deg,var(--gold),var(--blue-mid));height:100%;transition:width 0.8s ease;}}
.progress-pct{{font-family:var(--font-u);font-size:10px;color:var(--text-light);margin-top:3px;}}
.resource-link{{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid rgba(201,168,76,0.1);text-decoration:none;transition:color 0.2s;}}
.resource-link:last-child{{border-bottom:none;}}
.resource-link span{{font-family:var(--font-u);font-size:13px;font-weight:400;color:var(--text);}}
.resource-link:hover span{{color:var(--gold);}}
.resource-icon{{font-size:18px;width:28px;text-align:center;}}
.status-badge{{display:inline-block;font-family:var(--font-u);font-size:9px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;padding:3px 10px;}}
.status-active{{background:rgba(39,174,96,0.1);color:#27ae60;border:1px solid rgba(39,174,96,0.25);}}
.status-pending{{background:rgba(201,168,76,0.1);color:var(--gold);border:1px solid rgba(201,168,76,0.3);}}

/* ── DONOR SECTION ────────────────────────────────────── */
.impact-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:48px;}}
.impact-card{{background:rgba(255,255,255,0.68);backdrop-filter:blur(12px);border:1px solid rgba(201,168,76,0.2);padding:40px 32px;text-align:center;}}
.impact-amount{{font-family:var(--font-d);font-size:40px;font-weight:400;color:var(--gold);margin-bottom:8px;}}
.impact-label{{font-family:var(--font-u);font-size:11px;font-weight:500;letter-spacing:1.5px;text-transform:uppercase;color:var(--text-light);margin-bottom:12px;}}
.impact-desc{{font-family:var(--font-b);font-size:15px;font-style:italic;color:var(--text-light);line-height:1.6;}}

/* ── FOOTER ───────────────────────────────────────────── */
footer{{position:relative;z-index:5;padding:52px 48px 36px;text-align:center;}}
footer::before{{content:'';position:absolute;top:0;left:10%;right:10%;height:1px;background:linear-gradient(90deg,transparent,rgba(201,168,76,0.2),transparent);}}
.footer-brand{{font-family:var(--font-d);font-size:18px;font-weight:400;color:var(--text);margin-bottom:6px;}}
.footer-sub{{font-family:var(--font-u);font-size:10px;font-weight:300;letter-spacing:2px;text-transform:uppercase;color:var(--text-light);margin-bottom:20px;}}
.footer-links{{display:flex;justify-content:center;gap:32px;flex-wrap:wrap;margin-bottom:20px;}}
.footer-links a{{font-family:var(--font-u);font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--text-light);text-decoration:none;transition:color 0.2s;}}
.footer-links a:hover{{color:var(--gold);}}
.footer-verse{{font-family:var(--font-b);font-size:13px;font-style:italic;color:rgba(107,107,107,0.5);}}

/* ── REVEAL ───────────────────────────────────────────── */
.reveal{{opacity:0;transform:translateY(22px);transition:opacity 0.7s ease,transform 0.7s ease;}}
.reveal.visible{{opacity:1;transform:translateY(0);}}

/* ── RESPONSIVE ───────────────────────────────────────── */
@media(max-width:768px){{
  nav{{padding:0 20px;}}
  .nav-links{{display:none;}}
  section,.hero,footer{{padding-left:20px;padding-right:20px;}}
  .card-grid,.impact-grid{{grid-template-columns:1fr;}}
  .pathway-grid{{grid-template-columns:1fr 1fr;}}
  .stat-row{{gap:36px;}}
  .dash-grid{{grid-template-columns:1fr;}}
  .modal{{padding:36px 24px;}}
}}
</style>
</head>
