function openPathway(id) {{
  const p = pathways[id];
  if (!p) return;
  document.getElementById('pathway-modal-content').innerHTML = `
    <div style="font-size:40px;margin-bottom:16px;">${{p.icon}}</div>
    <div class="modal-title">${{p.title}}</div>
    <div class="modal-sub">${{p.desc}}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:24px;">
      <div class="dash-card" style="padding:16px;">
        <div class="dash-card-title">Duration</div>
        <div style="font-family:var(--font-d);font-size:18px;color:var(--text);">${{p.duration}}</div>
      </div>
      <div class="dash-card" style="padding:16px;">
        <div class="dash-card-title">Cost</div>
        <div style="font-family:var(--font-d);font-size:18px;color:var(--gold);">${{p.cost}}</div>
      </div>
      <div class="dash-card" style="padding:16px;">
        <div class="dash-card-title">Credential</div>
        <div style="font-family:var(--font-u);font-size:12px;color:var(--text);">${{p.credential}}</div>
      </div>
      <div class="dash-card" style="padding:16px;">
        <div class="dash-card-title">Earning Potential</div>
        <div style="font-family:var(--font-u);font-size:12px;color:var(--text);">${{p.salary}}</div>
      </div>
    </div>
    <div class="btn-row">
      <a href="${{p.link}}" target="_blank" class="btn-gold" style="font-size:10px;padding:12px 28px;">Start This Course Free ↗</a>
